  "format_version": 1,
  "profile_id": "alpha-measurement-v1",
  "revision": "1.0.0",
  "implementation_status": "specified_not_implemented",
  "engine_target": "PostgreSQL",
  "schema_fixture_versions": [
    "5.3",
    "5.4",
    "5.5"
  ],
  "support_claim": "Bounded specified profile on canonical fixtures; no executable analysis engine or full CDM certification yet.",
  "request_contract": {
    "required_keys": [
      "profile_id",
      "source_id",
      "window",
      "measurement_concept_ids",
      "output_scope",
      "disclosure_policy_id"
    ],
    "allowed_keys": [
      "profile_id",
      "source_id",
      "window",
      "measurement_concept_ids",
      "output_scope",
      "disclosure_policy_id"
    ],
    "concept_min": 1,
    "concept_max": 10,
    "concept_ids": "unique exact nonnegative integers <= 2147483647; 0 only by explicit selection; no descendants or implicit concept expansion",
    "window": "explicit inclusive ISO dates; start <= end; at most 120 touched calendar months; DATE columns only",
    "output_scope": [
      "restricted"
    ],
    "disclosure_policy_id": "nonempty versioned institutional policy ID; synthetic-unsuppressed-v1 is fixture-only"
  },
  "populations": {
    "source_context": "Exactly one selected source/schema snapshot; never join sources by person ID.",
    "person_table": "Accessible PERSON with unique non-null person_id; count all-source people independently of request window.",
    "valid_observation_people": "PERSON members with valid inclusive observation intervals. Merge overlap/adjacency per person, then clip to the request window.",
    "observed_measurement_rows": "Selected concept/date in inclusive request window, linked to PERSON, whose measurement_date belongs to at least one valid person observation period. Membership never multiplies rows.",
    "requested_outputs": "The fixed required_outputs list for one request/run."
  },
  "temporal_policy": {
    "date_column": "measurement_date",
    "timezone": "not_applied_to_DATE",
    "endpoints": "inclusive",
    "month_key": "YYYY-MM-01; period_start/end clipped to request window; partial edge months retained",
    "calendar": "proleptic Gregorian, ISO years 0001..9999; no 1900..2099 fixed calendar"
  },
  "preflight_policy": {
    "person_ids": "Null/duplicate person IDs fail PERSON-dependent outputs.",
    "observation_rows": "Null endpoints, end<start, or orphan person IDs fail observation-dependent outputs; do not silently drop malformed intervals.",
    "measurement_rows": "Selected in-window null/orphan person IDs fail measurement-dependent outputs; duplicate record IDs do not collapse physical rows.",
    "concept_rows": "Conflicting duplicate concept IDs fail terminology-dependent outputs; no matching positive unit ID is unknown, not a compatible unit.",
    "access": "Missing/inaccessible prerequisites produce unavailable reasons; never replace them with zero."
  },
  "availability_semantics": {
    "precedence": "Failed/inaccessible/unsupported prerequisites have no numeric value. Otherwise empty_source context (PERSON count 0) takes precedence over empty_population context (source people exist but a metric-specific eligible set is empty).",
    "zero": "A computed count can be exactly 0 when the relevant observed population exists but no selected event matches.",
    "numeric_empty": "An observed summary stratum with n=0 has empty_population and all statistic fields NULL; an unobserved stratum is not fabricated.",
    "completeness": "Every fixed requested output must be accounted for and validated. Failed/inaccessible/unsupported required computation prevents complete-alpha publication. Known empty results and verified policy-approved suppression can be complete; missing optional metadata remains explicitly unknown.",
    "wire_contract": "Exact status/value serialization and publication contracts are separate; retain these semantic distinctions."
  },
  "numeric_eligibility": [
    {
      "reason": "missing_numeric",
      "when": "value_as_number IS NULL"
    },
    {
      "reason": "non_finite_numeric",
      "when": "value_as_number is NaN or +/-Infinity"
    },
    {
      "reason": "explicit_operator",
      "when": "operator_concept_id is non-null and not 0; includes equality and all censored/unknown operators"
    },
    {
      "reason": "missing_unit",
      "when": "unit_concept_id IS NULL"
    },
    {
      "reason": "unmapped_unit",
      "when": "unit_concept_id = 0"
    },
    {
      "reason": "unknown_or_invalid_unit",
      "when": "unit_concept_id does not resolve uniquely to a positive Unit-domain concept"
    },
    {
      "reason": "eligible",
      "when": "all previous tests false"
    }
  ],
